const UNIT_BY_ID = new Map(UNITS.map(u => [u.id, u]));

/** Look up a unit by lowercase gameId/base id. */
export function getUnit(id: string | undefined | null): UnitDef | undefined {
  if (!id) return undefined;
  return UNIT_BY_ID.get(id.split(',')[0].trim().toLowerCase());
}

/** Canonical display name for a gameId, if known. */
export function getUnitName(id: string | undefined | null): string | undefined {
  return getUnit(id)?.name;
}

/** Local icon path for a gameId, if known. */
export function getUnitIcon(id: string | undefined | null): string | undefined {
  return getUnit(id)?.icon;
}
